body {
  margin: 0;
  background: #f3f4f6;
  color: #111827;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 16px;
}

.print-button {
  display: block;
  margin: 0 auto 14px;
  width: 180px;
  height: 40px;
  border: 0;
  border-radius: 7px;
  background: #111827;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.label-sheet {
  display: flex;
  justify-content: center;
}

.label-card {
  width: 148mm;
  min-height: 105mm;
  background: white;
  box-sizing: border-box;
  padding: 10mm;
  border: 1px solid #d1d5db;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.14);
}

.top {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 3px solid #111827;
  padding-bottom: 8px;
}

.eyebrow {
  font-size: 11px;
  color: #6b7280;
  font-weight: 900;
  letter-spacing: 0;
}

h1 {
  margin: 3px 0;
  font-size: 27px;
  line-height: 1.05;
}

.status {
  display: inline-block;
  padding: 4px 8px;
  background: #ecfdf5;
  color: #047857;
  font-size: 11px;
  font-weight: 900;
}

.qr {
  width: 34mm;
  height: 34mm;
}

.barcode-wrap {
  margin: 9px 0;
  text-align: center;
}

.barcode-wrap svg {
  width: 100%;
  max-height: 70px;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin: 9px 0;
}

.grid div,
.metrics div,
.dims,
.section {
  border: 1px solid #d1d5db;
  padding: 7px;
}

span {
  display: block;
  color: #6b7280;
  font-size: 10px;
  text-transform: uppercase;
  margin-bottom: 3px;
  font-weight: 800;
}

strong {
  font-size: 13px;
}

.section {
  margin-top: 8px;
  line-height: 1.35;
  font-size: 12px;
}

.section strong {
  display: block;
  font-size: 16px;
  margin-bottom: 3px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin-top: 8px;
}

.dims {
  margin-top: 8px;
}

.items {
  margin-top: 9px;
  border-top: 1px solid #d1d5db;
  padding-top: 7px;
}

.items-title {
  font-weight: 900;
  margin-bottom: 5px;
  font-size: 12px;
}

.item-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 0;
  border-bottom: 1px solid #f3f4f6;
  font-size: 11px;
}

.item-row span {
  display: inline;
  margin: 0;
  color: #111827;
  text-transform: none;
  font-weight: 600;
  font-size: 11px;
}

.item-row strong {
  white-space: nowrap;
  font-size: 11px;
}

.more {
  margin-top: 5px;
  font-size: 11px;
  color: #6b7280;
}

.footer {
  margin-top: 9px;
  padding-top: 6px;
  border-top: 1px solid #d1d5db;
  color: #6b7280;
  font-size: 10px;
  text-align: center;
}

.empty {
  background: white;
  padding: 24px;
  color: #6b7280;
  text-align: center;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .print-button,
  .no-print {
    display: none !important;
  }
  .label-sheet {
    display: block;
  }
  .label-card {
    width: 148mm;
    min-height: 105mm;
    margin: 0;
    box-shadow: none;
    border: 0;
    padding: 8mm;
    page-break-after: always;
  }
}

