import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function val(value) {
  return String(value ?? "");
}

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function formatDate(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("hr-HR");
}

function payload(label) {
  return [
    "PACKAGE",
    `PACKAGE_ID=${label.packageId || ""}`,
    `PACKAGE_NO=${label.packageNumber || ""}`,
    `BARCODE=${label.packageBarcode || ""}`,
    `DELIVERY=${label.deliveryNumber || ""}`,
    `SALES_ORDER=${label.salesOrderNumber || ""}`,
    `CUSTOMER=${label.customerName || ""}`,
    `QTY=${label.totalQuantity || ""}`
  ].join("|");
}

function barcodeValue(label) {
  return val(label.packageBarcode || label.packageNumber || "").replace(/[^A-Za-z0-9-]/g, "");
}

function App() {
  const model = appsmith.model || {};
  const label = model.label || {};
  const items = model.items || [];

  const [qr, setQr] = React.useState("");
  const barcodeRef = React.useRef(null);

  const key = `${label.packageId || ""}-${label.packageBarcode || ""}-${label.packageNumber || ""}`;

  React.useEffect(() => {
    async function buildQr() {
      if (!label.packageNumber) return;

      const code = await QRCode.toDataURL(payload(label), {
        margin: 1,
        width: 180,
        errorCorrectionLevel: "M"
      });

      setQr(code);
    }

    buildQr();
  }, [key]);

  React.useEffect(() => {
    const value = barcodeValue(label);

    if (!value || !barcodeRef.current) return;

    JsBarcode(barcodeRef.current, value, {
      format: "CODE128",
      displayValue: true,
      fontSize: 16,
      height: 58,
      margin: 0
    });
  }, [key]);

  if (!label.packageNumber) {
    return <div className="empty">No package label data available.</div>;
  }

  return (
    <div className="page">
      <button className="print-button no-print" onClick={() => window.print()}>
        Print label
      </button>

      <div className="label-sheet">
        <div className="label-card">
          <div className="top">
            <div>
              <div className="eyebrow">PACKAGE LABEL</div>
              <h1>{label.packageNumber}</h1>
              <div className="status">{label.packageStatus || "PACKED"}</div>
            </div>

            {qr && <img className="qr" src={qr} />}
          </div>

          <div className="barcode-wrap">
            <svg ref={barcodeRef}></svg>
          </div>

          <div className="grid">
            <div>
              <span>Delivery</span>
              <strong>{label.deliveryNumber || "-"}</strong>
            </div>
            <div>
              <span>Sales order</span>
              <strong>{label.salesOrderNumber || "-"}</strong>
            </div>
            <div>
              <span>Date</span>
              <strong>{formatDate(label.deliveryDate)}</strong>
            </div>
            <div>
              <span>Warehouse</span>
              <strong>{[label.warehouseCode, label.warehouseName].filter(Boolean).join(" - ") || "-"}</strong>
            </div>
          </div>

          <div className="section">
            <span>Ship To / Primatelj</span>
            <strong>{label.customerName || "-"}</strong>
            <div>{[label.customerAddress, label.customerPostalCode, label.customerCity].filter(Boolean).join(", ")}</div>
            <div>{[label.customerEmail, label.customerPhone].filter(Boolean).join(" | ")}</div>
          </div>

          <div className="metrics">
            <div>
              <span>Type</span>
              <strong>{label.packageType || "BOX"}</strong>
            </div>
            <div>
              <span>Items</span>
              <strong>{label.itemCount || items.length}</strong>
            </div>
            <div>
              <span>Qty</span>
              <strong>{qty(label.totalQuantity)}</strong>
            </div>
            <div>
              <span>Weight</span>
              <strong>{qty(label.grossWeight)} kg</strong>
            </div>
          </div>

          <div className="dims">
            <span>Dimensions</span>
            <strong>
              {qty(label.lengthCm)} x {qty(label.widthCm)} x {qty(label.heightCm)} cm
            </strong>
          </div>

          {items.length > 0 && (
            <div className="items">
              <div className="items-title">Contents</div>
              {items.slice(0, 6).map((item, index) => (
                <div className="item-row" key={index}>
                  <span>{item.productCode || ""} {item.productName || ""}</span>
                  <strong>{qty(item.quantity)} {item.unitCode || ""}</strong>
                </div>
              ))}
              {items.length > 6 && (
                <div className="more">+ {items.length - 6} more item(s)</div>
              )}
            </div>
          )}

          <div className="footer">
            {label.companyName || "Company"} · {label.companyPhone || ""} · {label.companyEmail || ""}
          </div>
        </div>
      </div>
    </div>
  );
}

function render(model = appsmith.model || {}) {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render(appsmith.model || {});
  appsmith.onModelChange((model) => render(model || {}));
});
